    geo2(0, 0, 1000, 0, 0, 0, 0, 0);
    geo(2, 1, 1, 382, 20, 45, 471, 480, 640, 1000, 0);
    geo2(2, 0, 500, 0, 0, 0, 0, 0);
    geo(3, 1, 1, 1035, 115, 12, 577, 480, 640, 1000, 0);
    geo2(3, 0, 1000, 0, 0, 0, 0, 0);
    geo(4, 0, 1, 309, 100, 54, 39, 50, 640, 806, 0);
    geo2(4, 4, 48, 0, 0, 0, 0, 0);
    prep3("@property --p { syntax: '<length>'; inherits: false; initial-value: 0px } @keyframes k { from { color: red; background-color: color(none xyz-d50 0.9667 0.0265 0.1) } 60% { color: oklch(none none none); background-color: hsla(61 98.9% none/none) } } @keyframes j { 33.33% { color: color(srgb-linear none 0.3877 1 /1.5); background-color: oklab(none 0.58 -0.1059 0.0617) } 50% { color: color(xyz-d65 none 0.69 0.29); background-color: hsl(540.208grad, 37.124%, 40.2688%, 1) } to { color: #cec; background-color: currentcolor } } html { overflow: hidden } body div { overflow: SCROLL clip; height: 0px !important } html { view-timeline-name: --v, --t; view-timeline-axis: x; scroll-timeline-name: --v, --t; view-timeline: --v inline; view-timeline-axis: y } body { view-timeline-name: --u; view-timeline-axis: x } #i { animation: k 1s, j 1000ms linear backwards; animation-timeline: --v, view(10px); animation-range: scroll entry-crossing -5% }", 500, 10000, 0, 1);
    TEST_ASSERT_EQUAL_STRING("", style_of("i"));
    TEST_ASSERT_EQUAL_STRING("0 1 0 0 1 2 1 1", counts());
    TEST_ASSERT_EQUAL_STRING("0000000110", flags());
    geo_root(1000, 646);
    geo(0, 1, 1, 41, 124, 31, 603, 480, 640, 1000, 0);
    geo2(0, 0, 1000, 0, 0, 0, 0, 0);
    geo(2, 1, 1, 1137, 34, 22, 252, 480, 640, 1000, 0);
    geo2(2, 0, 0, 0, 1, 200, 68, 100);
    geo(-1, 1, 1, 8, 1464, 8, 640, 480, 640, 1000, 0);
